1	import { BookingEntity, ExceptionHelper } from '@roombook/backend-common';
2	import { CreateBookingDto, ErrorCodeEnum, UpdateBookingDto } from '@roombook/contract';
3	import { INSTANT_GRAMMAR, parseInstant } from './booking-instant';
4	
5	export class NormalisedBookingDto {
6	  roomId: string;
7	  title: string;
8	  organizerEmail: string;
9	  startsAt: Date;
10	  endsAt: Date;
11	}
12	
13	export class BookingChangesDto {
14	  title?: string;
15	  startsAt?: Date;
16	  endsAt?: Date;
17	}
18	
19	const requireInstant = (field: string, value: unknown): Date =>
20	  parseInstant(value) ??
21	  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, `${field} must be an instant in the form ${INSTANT_GRAMMAR}`);
22	
23	export const rejectInvalidSpan = (): never =>
24	  ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');
25	
26	const requireSpan = (startsAt: Date, endsAt: Date): void => {
27	  if (endsAt.getTime() <= startsAt.getTime()) {
28	    rejectInvalidSpan();
29	  }
30	};
31	
32	export const normaliseCreateBooking = (body: CreateBookingDto): NormalisedBookingDto => {
33	  const startsAt = requireInstant('startsAt', body.startsAt);
34	  const endsAt = requireInstant('endsAt', body.endsAt);
35	  requireSpan(startsAt, endsAt);
36	  return {
37	    roomId: body.roomId.toLowerCase(),
38	    title: body.title,
39	    organizerEmail: body.organizerEmail,
40	    startsAt,
41	    endsAt,
42	  };
43	};
44	
45	export const parseBookingChanges = (changes: UpdateBookingDto): BookingChangesDto => {
46	  const parsed = new BookingChangesDto();
47	  if (changes.title !== undefined) {
48	    if (typeof changes.title !== 'string') {
49	      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'title must be a string');
50	    }
51	    parsed.title = changes.title;
52	  }
53	  if (changes.startsAt !== undefined) {
54	    parsed.startsAt = requireInstant('startsAt', changes.startsAt);
55	  }
56	  if (changes.endsAt !== undefined) {
57	    parsed.endsAt = requireInstant('endsAt', changes.endsAt);
58	  }
59	  return parsed;
60	};
61	
62	export const mergeBookingChanges = (stored: BookingEntity, changes: BookingChangesDto): BookingChangesDto => {
63	  const startsAt = changes.startsAt ?? stored.startsAt;
64	  const endsAt = changes.endsAt ?? stored.endsAt;
65	  requireSpan(startsAt, endsAt);
66	  const changed = new BookingChangesDto();
67	  if (changes.title !== undefined && changes.title !== stored.title) {
68	    changed.title = changes.title;
69	  }
70	  if (startsAt.getTime() !== stored.startsAt.getTime()) {
71	    changed.startsAt = startsAt;
72	  }
73	  if (endsAt.getTime() !== stored.endsAt.getTime()) {
74	    changed.endsAt = endsAt;
75	  }
76	  return changed;
77	};
