1	import { Injectable } from '@nestjs/common';
2	import { InjectRepository } from '@nestjs/typeorm';
3	import { BookingEntity, BOOKINGS_SPAN_CONSTRAINT } from '@roombook/backend-common';
4	import {
5	  BookingDto,
6	  ConfirmationStatusEnum,
7	  ListBookingsQueryDto,
8	  PagedBookingsDto,
9	  RecordConfirmationResultDto,
10	} from '@roombook/contract';
11	import { DataSource, LessThanOrEqual, Not, QueryFailedError, Repository } from 'typeorm';
12	import { BookingChangesDto, mergeBookingChanges, rejectInvalidSpan } from './booking-input';
13	
14	type ConstraintError = Error & { constraint?: string };
15	
16	export const toBookingDto = (entity: BookingEntity): BookingDto => ({
17	  id: entity.id,
18	  roomId: entity.roomId,
19	  title: entity.title,
20	  organizerEmail: entity.organizerEmail,
21	  startsAt: entity.startsAt.toISOString(),
22	  endsAt: entity.endsAt.toISOString(),
23	  confirmationStatus: entity.confirmationStatus,
24	  confirmationAttempts: entity.confirmationAttempts,
25	  createdAt: entity.createdAt.toISOString(),
26	  updatedAt: entity.updatedAt.toISOString(),
27	});
28	
29	export const violatedConstraint = (error: unknown): string | undefined =>
30	  error instanceof QueryFailedError ? (error.driverError as ConstraintError).constraint : undefined;
31	
32	export const rethrowSpanViolation = (error: unknown): never => {
33	  if (violatedConstraint(error) === BOOKINGS_SPAN_CONSTRAINT) {
34	    return rejectInvalidSpan();
35	  }
36	  throw error;
37	};
38	
39	@Injectable()
40	export class BookingRepository {
41	  constructor(
42	    @InjectRepository(BookingEntity) private readonly bookings: Repository<BookingEntity>,
43	    private readonly dataSource: DataSource,
44	  ) {}
45	
46	  async findPage(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
47	    const [entities, total] = await this.bookings.findAndCount({
48	      where: query.roomId ? { roomId: query.roomId } : {},
49	      order: { startsAt: 'ASC', id: 'ASC' },
50	      skip: (query.page - 1) * query.limit,
51	      take: query.limit,
52	    });
53	    return { items: entities.map(toBookingDto), total, page: query.page, limit: query.limit };
54	  }
55	
56	  async findById(id: string): Promise<BookingDto | null> {
57	    const entity = await this.bookings.findOneBy({ id });
58	    return entity ? toBookingDto(entity) : null;
59	  }
60	
61	  async deleteById(id: string): Promise<boolean> {
62	    const result = await this.bookings.delete({ id });
63	    return result.affected === 1;
64	  }
65	
66	  update(id: string, changes: BookingChangesDto): Promise<BookingDto | null> {
67	    return this.dataSource
68	      .transaction(async (manager) => {
69	        const stored = await manager.findOne(BookingEntity, { where: { id }, lock: { mode: 'pessimistic_write' } });
70	        if (!stored) {
71	          return null;
72	        }
73	        const changed = mergeBookingChanges(stored, changes);
74	        if (Object.keys(changed).length === 0) {
75	          return toBookingDto(stored);
76	        }
77	        await manager.update(BookingEntity, { id }, changed);
78	        return toBookingDto(await manager.findOneByOrFail(BookingEntity, { id }));
79	      })
80	      .catch(rethrowSpanViolation);
81	  }
82	
83	  async recordConfirmation(result: RecordConfirmationResultDto): Promise<BookingDto | null> {
84	    await this.bookings.update(
85	      {
86	        id: result.bookingId,
87	        confirmationStatus: Not(ConfirmationStatusEnum.SENT),
88	        confirmationAttempts: LessThanOrEqual(result.attempts),
89	      },
90	      { confirmationStatus: result.status, confirmationAttempts: result.attempts },
91	    );
92	    return this.findById(result.bookingId);
93	  }
94	}
