1	import { Injectable } from '@nestjs/common';
2	import { BookingEntity, IDEMPOTENCY_KEYS_PRIMARY_KEY, IdempotencyKeyEntity } from '@roombook/backend-common';
3	import { BookingDto, ConfirmationStatusEnum } from '@roombook/contract';
4	import { DataSource } from 'typeorm';
5	import { NormalisedBookingDto } from './booking-input';
6	import { rethrowSpanViolation, toBookingDto, violatedConstraint } from './booking.repository';
7	
8	export class IdempotentCreateDto {
9	  key: string;
10	  fingerprint: string;
11	  booking: NormalisedBookingDto;
12	}
13	
14	export type IdempotentCreateOutcome =
15	  | { kind: 'created'; booking: BookingDto }
16	  | { kind: 'replayed'; booking: BookingDto }
17	  | { kind: 'reused' }
18	  | { kind: 'in-progress' };
19	
20	type KeyLockRow = { obtained: boolean };
21	
22	const TRY_KEY_LOCK = 'SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0)) AS "obtained"';
23	
24	@Injectable()
25	export class IdempotentBookingRepository {
26	  constructor(private readonly dataSource: DataSource) {}
27	
28	  create(command: IdempotentCreateDto): Promise<IdempotentCreateOutcome> {
29	    const key = command.key.toLowerCase();
30	    return this.dataSource
31	      .transaction(async (manager): Promise<IdempotentCreateOutcome> => {
32	        const [lock]: KeyLockRow[] = await manager.query(TRY_KEY_LOCK, [key]);
33	        if (!lock.obtained) {
34	          return { kind: 'in-progress' };
35	        }
36	        const stored = await manager.findOneBy(IdempotencyKeyEntity, { key });
37	        if (stored) {
38	          return stored.fingerprint === command.fingerprint
39	            ? { kind: 'replayed', booking: stored.responseBody }
40	            : { kind: 'reused' };
41	        }
42	        const entity = await manager.save(BookingEntity, {
43	          ...command.booking,
44	          confirmationStatus: ConfirmationStatusEnum.PENDING,
45	          confirmationAttempts: 0,
46	        });
47	        const booking = toBookingDto(entity);
48	        await manager.insert(IdempotencyKeyEntity, { key, fingerprint: command.fingerprint, responseBody: booking });
49	        return { kind: 'created', booking };
50	      })
51	      .catch(
52	        (error: unknown): IdempotentCreateOutcome =>
53	          violatedConstraint(error) === IDEMPOTENCY_KEYS_PRIMARY_KEY
54	            ? { kind: 'in-progress' }
55	            : rethrowSpanViolation(error),
56	      );
57	  }
58	}
59

1	import { Inject, Injectable } from '@nestjs/common';
2	import { ClientProxy, RpcException } from '@nestjs/microservices';
3	import { ExceptionHelper, NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
4	import {
5	  BookingDto,
6	  BookingIdMessageDto,
7	  CreateBookingMessageDto,
8	  CreateBookingResultDto,
9	  ErrorCodeEnum,
10	  ListBookingsQueryDto,
11	  PagedBookingsDto,
12	  RecordConfirmationResultDto,
13	  RoomDto,
14	  RoomIdMessageDto,
15	  RoomPatternEnum,
16	  UpdateBookingMessageDto,
17	} from '@roombook/contract';
18	import { bookingFingerprint } from './booking-fingerprint';
19	import { normaliseCreateBooking, parseBookingChanges } from './booking-input';
20	import { BookingRepository } from './booking.repository';
21	import { ConfirmationProducer } from './confirmation.producer';
22	import { IdempotentBookingRepository, IdempotentCreateOutcome } from './idempotent-booking.repository';
23	
24	const toCreateResult = (outcome: IdempotentCreateOutcome): CreateBookingResultDto => {
25	  switch (outcome.kind) {
26	    case 'created':
27	      return { booking: outcome.booking, replayed: false };
28	    case 'replayed':
29	      return { booking: outcome.booking, replayed: true };
30	    case 'reused':
31	      return ExceptionHelper.unprocessable(
32	        ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED,
33	        'Idempotency-Key was already used for a different request body',
34	      );
35	    case 'in-progress':
36	      return ExceptionHelper.conflict(
37	        ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS,
38	        'A request with this Idempotency-Key is still being processed',
39	      );
40	  }
41	};
42	
43	const bookingNotFound = (id: string): never =>
44	  ExceptionHelper.notFound(ErrorCodeEnum.BOOKING_NOT_FOUND, `Booking ${id} was not found`);
45	
46	@Injectable()
47	export class BookingService {
48	  constructor(
49	    private readonly bookingRepository: BookingRepository,
50	    private readonly idempotentBookingRepository: IdempotentBookingRepository,
51	    private readonly confirmationProducer: ConfirmationProducer,
52	    @Inject(NATS_CLIENT) private readonly client: ClientProxy,
53	  ) {}
54	
55	  async createBooking(message: CreateBookingMessageDto): Promise<CreateBookingResultDto> {
56	    const booking = normaliseCreateBooking(message.booking);
57	    await this.requireRoom(booking.roomId);
58	    const outcome = await this.idempotentBookingRepository.create({
59	      key: message.idempotencyKey,
60	      fingerprint: bookingFingerprint(booking),
61	      booking,
62	    });
63	    const result = toCreateResult(outcome);
64	    await this.confirmationProducer.enqueue(result.booking.id);
65	    return result;
66	  }
67	
68	  listBookings(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
69	    return this.bookingRepository.findPage(query);
70	  }
71	
72	  async findBookingById(id: string): Promise<BookingDto> {
73	    const booking = await this.bookingRepository.findById(id);
74	    return booking ?? bookingNotFound(id);
75	  }
76	
77	  async updateBooking(message: UpdateBookingMessageDto): Promise<BookingDto> {
78	    const booking = await this.bookingRepository.update(message.id, parseBookingChanges(message.changes));
79	    return booking ?? bookingNotFound(message.id);
80	  }
81	
82	  async deleteBooking(id: string): Promise<BookingIdMessageDto> {
83	    const deleted = await this.bookingRepository.deleteById(id);
84	    return deleted ? { id } : bookingNotFound(id);
85	  }
86	
87	  async recordConfirmationResult(result: RecordConfirmationResultDto): Promise<BookingDto> {
88	    const booking = await this.bookingRepository.recordConfirmation(result);
89	    return booking ?? bookingNotFound(result.bookingId);
90	  }
91	
92	  private async requireRoom(roomId: string): Promise<void> {
93	    await NatsRequestUtil.send<RoomDto, RoomIdMessageDto>(this.client, RoomPatternEnum.FIND_BY_ID, {
94	      id: roomId,
95	    }).catch((error: unknown) => {
96	      // The room service's own answer arrives as a plain object; only an RpcException crosses NATS intact.
97	      throw error instanceof RpcException ? error : new RpcException(error as object);
98	    });
99	  }
100	}
