1	import { InjectQueue } from '@nestjs/bullmq';
2	import { Injectable, Logger } from '@nestjs/common';
3	import { ExceptionHelper } from '@roombook/backend-common';
4	import {
5	  CONFIRMATION_BACKOFF_MS,
6	  CONFIRMATION_JOB_ATTEMPTS,
7	  ConfirmationJobDto,
8	  confirmationJobId,
9	  ErrorCodeEnum,
10	  QueueEnum,
11	} from '@roombook/contract';
12	import { Queue } from 'bullmq';
13	import { from, lastValueFrom, timeout } from 'rxjs';
14	
15	export const CONFIRMATION_ENQUEUE_TIMEOUT_MS = 2000;
16	
17	@Injectable()
18	export class ConfirmationProducer {
19	  private readonly logger = new Logger(ConfirmationProducer.name);
20	
21	  constructor(@InjectQueue(QueueEnum.BOOKING_CONFIRMATION) private readonly queue: Queue<ConfirmationJobDto>) {}
22	
23	  async enqueue(bookingId: string): Promise<void> {
24	    const adding = this.queue.add(
25	      QueueEnum.BOOKING_CONFIRMATION,
26	      { bookingId },
27	      {
28	        jobId: confirmationJobId(bookingId),
29	        attempts: CONFIRMATION_JOB_ATTEMPTS,
30	        backoff: { type: 'exponential', delay: CONFIRMATION_BACKOFF_MS },
31	        // Kept by decision: the job id of a finished job is what blocks a second job for the booking.
32	        removeOnComplete: false,
33	        removeOnFail: false,
34	      },
35	    );
36	    try {
37	      await lastValueFrom(from(adding).pipe(timeout(CONFIRMATION_ENQUEUE_TIMEOUT_MS)));
38	    } catch (error) {
39	      const reason = error instanceof Error ? error.message : String(error);
40	      this.logger.error(`Confirmation job for booking ${bookingId} was not enqueued: ${reason}`);
41	      ExceptionHelper.serviceUnavailable(ErrorCodeEnum.SERVICE_UNAVAILABLE, 'Confirmation queue is unavailable');
42	    }
43	  }
44	}
