2	import { Inject, Logger } from '@nestjs/common';
3	import { ClientProxy } from '@nestjs/microservices';
4	import { NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
5	import {
6	  BookingDto,
7	  BookingIdMessageDto,
8	  BookingPatternEnum,
9	  CONFIRMATION_JOB_ATTEMPTS,
10	  ConfirmationJobDto,
11	  ConfirmationStatusEnum,
12	  ErrorCodeEnum,
13	  QueueEnum,
14	  RecordConfirmationResultDto,
15	} from '@roombook/contract';
16	import { Job } from 'bullmq';
17	import { simulateConfirmationSend } from './simulated-confirmation-sender';
18	
19	const isBookingNotFound = (error: unknown): boolean =>
20	  typeof error === 'object' &&
21	  error !== null &&
22	  (error as Record<string, unknown>)['errorCode'] === ErrorCodeEnum.BOOKING_NOT_FOUND;
23	
24	const statusOf = (sent: boolean, attempt: number): ConfirmationStatusEnum => {
25	  if (sent) {
26	    return ConfirmationStatusEnum.SENT;
27	  }
28	  return attempt < CONFIRMATION_JOB_ATTEMPTS ? ConfirmationStatusEnum.PENDING : ConfirmationStatusEnum.FAILED;
29	};
30	
31	@Processor(QueueEnum.BOOKING_CONFIRMATION)
32	export class ConfirmationProcessor extends WorkerHost {
33	  private readonly logger = new Logger(ConfirmationProcessor.name);
34	
35	  constructor(@Inject(NATS_CLIENT) private readonly client: ClientProxy) {
36	    super();
37	  }
38	
39	  async process(job: Job<ConfirmationJobDto>): Promise<void> {
40	    const { bookingId } = job.data;
41	    const attempt = job.attemptsMade + 1;
42	    const booking = await this.readBooking(bookingId);
43	    if (!booking || booking.confirmationStatus === ConfirmationStatusEnum.SENT) {
44	      return;
45	    }
46	    const sent = simulateConfirmationSend(booking.organizerEmail, attempt);
47	    const recorded = await this.report({ bookingId, status: statusOf(sent, attempt), attempts: attempt });
48	    if (recorded && !sent) {
49	      throw new Error(`Confirmation for booking ${bookingId} was not sent on attempt ${attempt}`);
50	    }
51	  }
52	
53	  private readBooking(bookingId: string): Promise<BookingDto | null> {
54	    return NatsRequestUtil.send<BookingDto, BookingIdMessageDto>(this.client, BookingPatternEnum.FIND_BY_ID, {
55	      id: bookingId,
56	    }).catch((error: unknown) => {
57	      if (isBookingNotFound(error)) {
58	        return null;
59	      }
60	      throw error;
61	    });
62	  }
63	
64	  private report(result: RecordConfirmationResultDto): Promise<BookingDto | null> {
65	    return NatsRequestUtil.send<BookingDto, RecordConfirmationResultDto>(
66	      this.client,
67	      BookingPatternEnum.RECORD_CONFIRMATION,
68	      result,
69	    ).catch((error: unknown) => {
70	      if (isBookingNotFound(error)) {
71	        return null;
72	      }
73	      this.logger.error(
74	        `Confirmation result ${result.status} (attempt ${result.attempts}) for booking ${result.bookingId} was not recorded`,
75	      );
76	      throw error;
77	    });
78	  }
79	}
