1	import { BOUNCE_EMAIL_DOMAIN, CONFIRMATION_JOB_ATTEMPTS, RETRY_EMAIL_DOMAIN } from '@roombook/contract';
2	
3	export const simulateConfirmationSend = (organizerEmail: string, attempt: number): boolean => {
4	  const domain = organizerEmail.slice(organizerEmail.lastIndexOf('@') + 1).toLowerCase();
5	  if (domain === BOUNCE_EMAIL_DOMAIN) {
6	    return false;
7	  }
8	  return domain !== RETRY_EMAIL_DOMAIN || attempt >= CONFIRMATION_JOB_ATTEMPTS;
9	};
