2	import { BaseExceptionFilter } from '@nestjs/core';
3	import { RpcException } from '@nestjs/microservices';
4	import { ErrorCodeEnum, ErrorResponseDto } from '@roombook/contract';
5	
6	const isErrorResponse = (value: unknown): value is ErrorResponseDto => {
7	  if (typeof value !== 'object' || value === null) {
8	    return false;
9	  }
10	  const candidate = value as Record<string, unknown>;
11	  return (
12	    typeof candidate['statusCode'] === 'number' &&
13	    typeof candidate['errorCode'] === 'string' &&
14	    typeof candidate['message'] === 'string'
15	  );
16	};
17	
18	const validationMessage = (exception: BadRequestException): string => {
19	  const response = exception.getResponse();
20	  const message = typeof response === 'object' ? (response as Record<string, unknown>)['message'] : response;
21	  return Array.isArray(message) ? message.join(', ') : String(message);
22	};
23	
24	@Catch()
25	export class RpcExceptionFilter extends BaseExceptionFilter {
26	  override catch(exception: unknown, host: ArgumentsHost): void {
27	    const body = this.toErrorResponse(exception);
28	    if (!body) {
29	      return super.catch(exception, host);
30	    }
31	    const httpAdapter = this.applicationRef ?? this.httpAdapterHost?.httpAdapter;
32	    httpAdapter?.reply(host.switchToHttp().getResponse(), body, body.statusCode);
33	  }
34	
35	  private toErrorResponse(exception: unknown): ErrorResponseDto | null {
36	    const error = exception instanceof RpcException ? exception.getError() : exception;
37	    if (isErrorResponse(error)) {
38	      return { statusCode: error.statusCode, errorCode: error.errorCode, message: error.message };
39	    }
40	    if (exception instanceof BadRequestException) {
41	      return {
42	        statusCode: HttpStatus.BAD_REQUEST,
43	        errorCode: ErrorCodeEnum.VALIDATION,
44	        message: validationMessage(exception),
45	      };
46	    }
47	    return null;
48	  }
49	}
