2	import { DEFAULT_PAGE_SIZE } from '@roombook/contract';
3	import type { PagedBookingsDto } from '@roombook/contract';
4	import { listBookings } from '../../services/booking.service';
5	import { errorMessage } from './error-message';
6	
7	const lastPageOf = (result: PagedBookingsDto): number => Math.max(1, Math.ceil(result.total / result.limit));
8	
9	export function useBookingsList() {
10	  const [page, setPage] = useState(1);
11	  const [roomId, setRoomId] = useState('');
12	  const [fetchCount, setFetchCount] = useState(0);
13	  const [result, setResult] = useState<PagedBookingsDto | null>(null);
14	  const [loading, setLoading] = useState(true);
15	  const [error, setError] = useState<string | null>(null);
16	
17	  useEffect(() => {
18	    let active = true;
19	    setLoading(true);
20	    setError(null);
21	    listBookings({ page, limit: DEFAULT_PAGE_SIZE, ...(roomId && { roomId }) })
22	      .then((data) => {
23	        if (!active) return;
24	        if (data.items.length === 0 && page > lastPageOf(data)) {
25	          setPage(lastPageOf(data));
26	          return;
27	        }
28	        setResult(data);
29	        setLoading(false);
30	      })
31	      .catch((e: unknown) => {
32	        if (!active) return;
33	        setError(errorMessage(e));
34	        setLoading(false);
35	      });
36	    return () => {
37	      active = false;
38	    };
39	  }, [page, roomId, fetchCount]);
40	
41	  const filterByRoom = useCallback((nextRoomId: string) => {
42	    setRoomId(nextRoomId);
43	    setPage(1);
44	  }, []);
45	
46	  const refetch = useCallback(() => setFetchCount((count) => count + 1), []);
47	
48	  return { roomId, result, loading, error, goToPage: setPage, filterByRoom, refetch };
49	}
