7	const loadEveryRoom = async (): Promise<RoomDto[]> => {
8	  const rooms: RoomDto[] = [];
9	  for (let page = 1; ; page += 1) {
10	    const { items, total } = await listRooms(page, DEFAULT_PAGE_SIZE);
11	    rooms.push(...items);
12	    if (items.length === 0 || rooms.length >= total) return rooms;
13	  }
