16	export function useAllRooms() {
17	  const [rooms, setRooms] = useState<RoomDto[]>([]);
18	  const [error, setError] = useState<string | null>(null);
19	
20	  useEffect(() => {
21	    let active = true;
22	    loadEveryRoom()
23	      .then((loaded) => active && setRooms(loaded))
24	      .catch((e: unknown) => active && setError(errorMessage(e)));
25	    return () => {
26	      active = false;
27	    };
28	  }, []);
29	
30	  return { rooms, error };
31	}
