1	import { execFileSync } from 'child_process';
2	import { join } from 'path';
3	import { parseInstant } from './booking-instant';
4	
5	class ZoneRunDto {
6	  offsetMinutes: number;
7	  results: Array<string | null>;
8	}
9	
10	const TZ_INPUTS = [
11	  '2030-01-07T09:00',
12	  '2030-01-07T09:00:00',
13	  '2030-01-07T16:00:00+07:00',
14	  '2030-01-07T09:00:00Z',
15	  '2030-01-07T09:00:00.5Z',
16	];
17	
18	// Jest hands specs a copy of process.env, so TZ only takes effect in a fresh process.
19	const parseUnderTimeZone = (timeZone: string): ZoneRunDto => {
20	  const script = `
21	    require(${JSON.stringify(require.resolve('ts-node'))}).register({
22	      transpileOnly: true,
23	      compilerOptions: { module: 'commonjs' },
24	    });
25	    const { parseInstant } = require(${JSON.stringify(join(__dirname, 'booking-instant.ts'))});
26	    const results = ${JSON.stringify(TZ_INPUTS)}.map((input) => {
27	      const parsed = parseInstant(input);
28	      return parsed ? parsed.toISOString() : null;
29	    });
30	    console.log(JSON.stringify({ offsetMinutes: new Date(2030, 0, 7, 9).getTimezoneOffset(), results }));
31	  `;
32	  const output = execFileSync(process.execPath, ['-e', script], {
33	    env: { ...process.env, TZ: timeZone },
34	    encoding: 'utf8',
35	  });
36	  return JSON.parse(output) as ZoneRunDto;
37	};
38	
39	describe('parseInstant (BKG-003)', () => {
40	  it.each([
41	    ['2030-01-07T09:00:00Z', '2030-01-07T09:00:00.000Z'],
42	    ['2030-01-07T09:00:00.000Z', '2030-01-07T09:00:00.000Z'],
43	    ['2030-01-07T09:00:00.1Z', '2030-01-07T09:00:00.100Z'],
44	    ['2030-01-07T09:00:00.12Z', '2030-01-07T09:00:00.120Z'],
45	    ['2030-01-07T09:00:00.123Z', '2030-01-07T09:00:00.123Z'],
46	    ['2030-01-07T16:00:00+07:00', '2030-01-07T09:00:00.000Z'],
47	    ['2030-01-07T10:00:00+01:00', '2030-01-07T09:00:00.000Z'],
48	    ['2030-01-07T03:30:00-05:30', '2030-01-07T09:00:00.000Z'],
49	    ['2030-01-07T09:00:00+00:00', '2030-01-07T09:00:00.000Z'],
50	    ['2028-02-29T23:59:59.999Z', '2028-02-29T23:59:59.999Z'],
51	  ])('reads %s as the instant %s', (input, expected) => {
52	    expect(parseInstant(input)?.toISOString()).toBe(expected);
53	  });
54	
55	  it.each([
56	    ['no offset, minutes only', '2030-01-07T09:00'],
57	    ['no offset', '2030-01-07T09:00:00'],
58	    ['date only', '2030-01-07'],
59	    ['week date', '2030-W02-1T09:00:00Z'],
60	    ['ordinal date', '2030-007T09:00:00Z'],
61	    ['more than three fraction digits', '2030-01-07T09:00:00.123456Z'],
62	    ['lower case designators', '2030-01-07t09:00:00z'],
63	    ['a day that does not exist', '2030-02-30T09:00:00Z'],
64	    ['29 February of a common year', '2030-02-29T09:00:00Z'],
65	    ['month 13', '2030-13-01T09:00:00Z'],
66	    ['hour 24', '2030-01-07T24:00:00Z'],
67	    ['minute 60', '2030-01-07T09:60:00Z'],
68	    ['second 60', '2030-01-07T09:00:60Z'],
69	    ['an empty fraction', '2030-01-07T09:00:00.Z'],
70	    ['an offset without a colon', '2030-01-07T16:00:00+0700'],
71	    ['an offset of hours only', '2030-01-07T16:00:00+07'],
72	    ['an offset hour past 23', '2030-01-07T16:00:00+24:00'],
73	    ['an offset minute past 59', '2030-01-07T16:00:00+07:60'],
74	    ['a space instead of T', '2030-01-07 09:00:00Z'],
75	    ['surrounding white space', ' 2030-01-07T09:00:00Z '],
76	    ['a trailing line break', '2030-01-07T09:00:00Z\n'],
77	    ['an empty string', ''],
78	  ])('rejects %s', (_case, input) => {
79	    expect(parseInstant(input)).toBeNull();
80	  });
81	
82	  it.each([[null], [undefined], [1893488400000], [new Date('2030-01-07T09:00:00Z')], [{}]])(
