1	import { act, renderHook } from '@testing-library/react';
2	import { ErrorCodeEnum } from '@roombook/contract';
3	import { ApiError } from '../../services/api-error';
4	import { useIdempotencyKey } from './use-idempotency-key';
5	
6	const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
7	
8	const payload = { title: 'Sprint planning', startsAt: '2030-01-07T09:00:00.000Z' };
9	
10	const apiError = (statusCode: number, errorCode: ErrorCodeEnum) =>
11	  new ApiError({ statusCode, errorCode, message: 'failed' });
12	
13	const setup = () => renderHook(() => useIdempotencyKey()).result;
14	
15	describe('useIdempotencyKey (BPG-006, R-14)', () => {
16	  it('issues a UUID', () => {
17	    expect(setup().current.keyFor(payload)).toMatch(UUID_PATTERN);
18	  });
19	
20	  it('keeps the key for the retry of an unchanged payload after a 503', () => {
21	    const hook = setup();
22	    const first = hook.current.keyFor(payload);
23	    act(() => hook.current.settle(apiError(503, ErrorCodeEnum.SERVICE_UNAVAILABLE)));
24	
25	    expect(hook.current.keyFor({ ...payload })).toBe(first);
26	  });
27	
28	  it('keeps the key after a network error', () => {
29	    const hook = setup();
30	    const first = hook.current.keyFor(payload);
31	    act(() => hook.current.settle(new Error('Network Error')));
32	
33	    expect(hook.current.keyFor(payload)).toBe(first);
34	  });
35	
36	  it('keeps the key after a 409 in-progress answer', () => {
37	    const hook = setup();
38	    const first = hook.current.keyFor(payload);
39	    act(() => hook.current.settle(apiError(409, ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS)));
40	
41	    expect(hook.current.keyFor(payload)).toBe(first);
42	  });
43	
44	  it('issues a new key when the payload was edited after a 503', () => {
45	    const hook = setup();
46	    const first = hook.current.keyFor(payload);
47	    act(() => hook.current.settle(apiError(503, ErrorCodeEnum.SERVICE_UNAVAILABLE)));
48	
49	    const second = hook.current.keyFor({ ...payload, title: 'Retro' });
50	
51	    expect(second).toMatch(UUID_PATTERN);
52	    expect(second).not.toBe(first);
53	  });
54	
55	  it('drops the key after a 201', () => {
56	    const hook = setup();
57	    const first = hook.current.keyFor(payload);
58	    act(() => hook.current.settle());
59	
60	    expect(hook.current.keyFor(payload)).not.toBe(first);
61	  });
62	
63	  it.each([
64	    [400, ErrorCodeEnum.VALIDATION],
65	    [404, ErrorCodeEnum.ROOM_NOT_FOUND],
66	    [422, ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED],
67	  ])('drops the key after a final %i answer', (statusCode, errorCode) => {
68	    const hook = setup();
69	    const first = hook.current.keyFor(payload);
70	    act(() => hook.current.settle(apiError(statusCode, errorCode)));
71	
72	    expect(hook.current.keyFor(payload)).not.toBe(first);
73	  });
74	
75	  it('keeps the key across re-renders', () => {
76	    const { result, rerender } = renderHook(() => useIdempotencyKey());
77	    const first = result.current.keyFor(payload);
78	    rerender();
79	
80	    expect(result.current.keyFor(payload)).toBe(first);
81	  });
82	});
