10	const ID = '9d0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a99';
11	const { PENDING, SENT, FAILED } = ConfirmationStatusEnum;
12	const NOT_FOUND = { statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND, message: 'gone' };
13	const unavailable = (): RpcException =>
14	  new RpcException({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE, message: 'down' });
15	
16	const job = (attemptsMade: number): Job<ConfirmationJobDto> =>
17	  ({ data: { bookingId: ID }, attemptsMade }) as Job<ConfirmationJobDto>;
18	
19	describe('ConfirmationProcessor', () => {
20	  let processor: ConfirmationProcessor;
21	  const send = jest.fn();
22	  let stored = { id: ID, organizerEmail: 'ann@example.com', confirmationStatus: PENDING, confirmationAttempts: 0 };
23	
24	  const reports = (): unknown[] =>
25	    send.mock.calls.filter(([pattern]) => pattern === BookingPatternEnum.RECORD_CONFIRMATION).map(([, data]) => data);
26	
27	  const answer = (read: () => Observable<unknown>, report: () => Observable<unknown>): void => {
28	    send.mockImplementation((pattern: string) => (pattern === BookingPatternEnum.FIND_BY_ID ? read() : report()));
29	  };
30	
31	  const runAttempts = async (organizerEmail: string): Promise<string[]> => {
32	    stored = { ...stored, organizerEmail };
33	    const results: string[] = [];
34	    for (const attemptsMade of [0, 1, 2]) {
35	      results.push(
36	        await processor.process(job(attemptsMade)).then(
37	          () => 'completed',
38	          () => 'failed',
39	        ),
40	      );
41	      if (results[attemptsMade] === 'completed') {
42	        break;
43	      }
44	    }
45	    return results;
46	  };
47	
48	  beforeEach(async () => {
49	    jest.resetAllMocks();
50	    jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
51	    stored = { id: ID, organizerEmail: 'ann@example.com', confirmationStatus: PENDING, confirmationAttempts: 0 };
52	    answer(
53	      () => of(stored),
54	      () => of(stored),
55	    );
56	    const moduleRef = await Test.createTestingModule({
57	      providers: [ConfirmationProcessor, { provide: NATS_CLIENT, useValue: { send } }],
58	    }).compile();
59	    processor = moduleRef.get(ConfirmationProcessor);
60	  });
61	
62	  afterEach(() => jest.restoreAllMocks());
63	
64	  it('reports SENT 1 for a plain address and completes (CNF-005)', async () => {
65	    await expect(runAttempts('ann@example.com')).resolves.toEqual(['completed']);
66	
67	    expect(send).toHaveBeenNthCalledWith(1, BookingPatternEnum.FIND_BY_ID, { id: ID });
68	    expect(reports()).toEqual([{ bookingId: ID, status: SENT, attempts: 1 }]);
69	  });
70	
71	  it('reports PENDING 1, PENDING 2, SENT 3 for a retry address, failing the first two runs (CNF-005)', async () => {
72	    await expect(runAttempts('ann@retry.example')).resolves.toEqual(['failed', 'failed', 'completed']);
73	
74	    expect(reports()).toEqual([
75	      { bookingId: ID, status: PENDING, attempts: 1 },
76	      { bookingId: ID, status: PENDING, attempts: 2 },
77	      { bookingId: ID, status: SENT, attempts: 3 },
78	    ]);
79	  });
80	
81	  it('reports PENDING 1, PENDING 2, FAILED 3 for a bounce address, failing every run (CNF-005)', async () => {
82	    await expect(runAttempts('ann@bounce.example')).resolves.toEqual(['failed', 'failed', 'failed']);
83	
84	    expect(reports()).toEqual([
85	      { bookingId: ID, status: PENDING, attempts: 1 },
86	      { bookingId: ID, status: PENDING, attempts: 2 },
87	      { bookingId: ID, status: FAILED, attempts: 3 },
88	    ]);
89	  });
90	
91	  it('CNF-007: completes without sending or reporting when the booking already reads SENT', async () => {
92	    stored = { ...stored, organizerEmail: 'ann@bounce.example', confirmationStatus: SENT, confirmationAttempts: 1 };
93	
94	    await expect(processor.process(job(0))).resolves.toBeUndefined();
95	
96	    expect(reports()).toEqual([]);
97	  });
98	
99	  it('CNF-007: completes without reporting when the read answers 404 NOT_FOUND.BOOKING', async () => {
100	    answer(
101	      () => throwError(() => NOT_FOUND),
102	      () => of(stored),
103	    );
104	
105	    await expect(processor.process(job(0))).resolves.toBeUndefined();
106	
107	    expect(reports()).toEqual([]);
108	  });
109	
110	  it('CNF-007: completes, even for a failed send, when the report answers 404 NOT_FOUND.BOOKING', async () => {
111	    stored = { ...stored, organizerEmail: 'ann@bounce.example' };
112	    answer(
113	      () => of(stored),
114	      () => throwError(() => NOT_FOUND),
115	    );
116	
117	    await expect(processor.process(job(0))).resolves.toBeUndefined();
118	
119	    expect(reports()).toEqual([{ bookingId: ID, status: PENDING, attempts: 1 }]);
120	  });
121	
122	  it('fails the job for a retry when the read answers 503, without reporting (CNF-007)', async () => {
123	    const down = unavailable();
124	    answer(
125	      () => throwError(() => down),
126	      () => of(stored),
127	    );
128	
129	    await expect(processor.process(job(0))).rejects.toBe(down);
130	    expect(reports()).toEqual([]);
131	  });
132	
133	  it('fails the job for a retry and logs when the report answers 503 (CNF-007)', async () => {
134	    const down = unavailable();
135	    answer(
136	      () => of(stored),
137	      () => throwError(() => down),
138	    );
139	
140	    await expect(processor.process(job(0))).rejects.toBe(down);
141	    expect(Logger.prototype.error).toHaveBeenCalledWith(expect.stringContaining(ID));
142	  });
143	
144	  it('fails the job on any other error of the read, such as another 404 (CNF-007)', async () => {
145	    const other = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' };
146	    answer(
147	      () => throwError(() => other),
148	      () => of(stored),
149	    );
150	
151	    await expect(processor.process(job(0))).rejects.toBe(other);
152	  });
153	});
